module stimulus_gen
#(parameter N=7)
(
	input clk,
	output logic areset,

	output logic predict_valid,
	output [N-1:0] predict_pc,

	output logic train_valid,
	output train_taken,
	output train_mispredicted,
	output [N-1:0] train_history,
	output [N-1:0] train_pc,

